import React, { useState, useEffect } from "react";
import "./AdminDashboard.css"; // Create this CSS file

export default function AdminDashboard() {
    const [selectedBranch, setSelectedBranch] = useState(null);
    const [employees, setEmployees] = useState([]);
    const [loading, setLoading] = useState(false);

    const branches = ["Hitech City", "Vanasthalipuram", "Nagole"]; // Or fetch dynamically

    useEffect(() => {
        // Protect route
        const role = localStorage.getItem("role");
        if (role !== "admin") {
            window.location.href = "/login";
        }
    }, []);

    const fetchEmployees = async (branch) => {
        setLoading(true);
        try {
            const res = await fetch(`http://localhost:5000/api/user/branch/${encodeURIComponent(branch)}`);
            const data = await res.json();
            setEmployees(data);
            setSelectedBranch(branch);
        } catch (err) {
            alert("Failed to load employees");
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    const handleLogout = () => {
        localStorage.clear();
        window.location.href = "/login";
    };

    return (
        <div className="admin-dashboard">
            <div className="admin-header">
                <h1>Admin Dashboard</h1>
                <button className="logout-btn" onClick={handleLogout}>
                    Logout
                </button>
            </div>

            {/* Branch Cards */}
            <div className="branches-grid">
                {branches.map((branch) => (
                    <div
                        key={branch}
                        className={`branch-card ${selectedBranch === branch ? "active" : ""}`}
                        onClick={() => fetchEmployees(branch)}
                    >
                        <h3>{branch}</h3>
                        <p>Click to view employees</p>
                    </div>
                ))}
            </div>

            {/* Employees Table */}
            {selectedBranch && (
                <div className="employees-section">
                    <h2>Employees in {selectedBranch}</h2>

                    {loading ? (
                        <p>Loading employees...</p>
                    ) : employees.length === 0 ? (
                        <p>No employees in this branch yet.</p>
                    ) : (
                        <table className="employees-table">
                            <thead>
                                <tr>
                                    <th>Name</th>
                                    <th>Employee ID</th>
                                    <th>Designation</th>
                                    <th>Email</th>
                                    <th>Phone</th>
                                    <th>View</th>
                                </tr>
                            </thead>
                            <tbody>
                                {employees.map((emp) => (
                                    <tr key={emp._id}>
                                        <td>{emp.name}</td>
                                        <td>{emp.userId}</td>
                                        <td>{emp.designation}</td>
                                        <td>{emp.email}</td>
                                        <td>{emp.phone || "-"}</td>
                    // Inside the employees table row
                                        <td>
                                            <button
                                                className="view-attendance-btn"
                                                onClick={() => {
                                                    // Store employee data temporarily and navigate
                                                    localStorage.setItem("viewAttendanceEmployee", JSON.stringify(emp));
                                                    window.location.href = "/attendance-details";
                                                }}
                                            >
                                                View Attendance
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    )}
                </div>
            )}
        </div>
    );
}
